      // make the sign counter-intuitive.
      await animateToPixels(pos.pixels + delta);
      await WidgetsBinding.instance.endOfFrame;
      if (isMounted() && overlaps()) return;

      await animateToPixels(pos.pixels - delta);
      await WidgetsBinding.instance.endOfFrame;
      return;
