/// B-015 / B-031: centre the row for [path] in view; skips when the track
/// isn't in the current folder.
Future<void> scrollToTrack(String path) async {
  if (!isMounted()) return;
  final tracks = ctrl.tracks;
  final index = tracks.indexWhere((t) => t.path == path);
  if (index < 0) return;
  if (!scroll.hasClients) return;

  Future<void> animateToPixels(double targetPixels) async {
    final pos = scroll.position;
    final target = targetPixels
        .clamp(pos.minScrollExtent, pos.maxScrollExtent)
        .toDouble();
    await scroll.animateTo(
      target,
      duration: const Duration(milliseconds: 240),
      curve: Curves.easeOutCubic,
    );
  }

  // Prefer a geometric delta computed from render boxes: this keeps the
  // behaviour aligned with the clipped viewport actually used on desktop.
  final rowContext = rowKeys[path]?.currentContext;
  final viewportContext = listViewportKey.currentContext;
  final rowRO = rowContext?.findRenderObject();
  final viewportRO = viewportContext?.findRenderObject();

  if (rowRO is RenderBox && viewportRO is RenderBox) {
    if (rowRO.hasSize && viewportRO.hasSize) {
      Rect rowRect() => rowRO.localToGlobal(Offset.zero) & rowRO.size;
      Rect viewportRect() =>
          viewportRO.localToGlobal(Offset.zero) & viewportRO.size;
      bool overlaps() => rowRect().overlaps(viewportRect());

      final delta = rowRect().center.dy - viewportRect().center.dy;
      final pos = scroll.position;

      // Try both directions: scroll-axis orientation on reverse lists can
      // make the sign counter-intuitive.
      await animateToPixels(pos.pixels + delta);
      await WidgetsBinding.instance.endOfFrame;
      if (isMounted() && overlaps()) return;

      await animateToPixels(pos.pixels - delta);
      await WidgetsBinding.instance.endOfFrame;
      return;
    }
  }

  // Fallback: reverse-axis mapping based centre.
  final pos = scroll.position;
  final childIndex = tracks.length - 1 - index;

  // ignore: use_build_context_synchronously
  var rowHeight = Theme.of(context).extension<AppGeometry>()!.rowHeight;
  for (final key in rowKeys.values) {
    final box = key.currentContext?.findRenderObject();
    if (box is RenderBox && box.hasSize) {
      rowHeight = box.size.height;
      break;
    }
  }

  final target = (childIndex * rowHeight -
          pos.viewportDimension / 2 +
          rowHeight / 2)
      .clamp(pos.minScrollExtent, pos.maxScrollExtent);
  await animateToPixels(target);
}
